package cn.zhinan.admincredentialcrypto;

import static org.assertj.core.api.Assertions.*;

import cn.zhinan.adminsecurity.domain.CredentialDependencyException;
import java.util.Arrays;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class Argon2PasswordServiceTest {
  // Independently generated by argon2-cffi 25.1.0, UTF-8, salt=ASCII 0123456789abcdef.
  private static final String PASSWORD = "synthetic fixture é 👩‍💻  ";
  static final String CURRENT =
      "$argon2id$v=19$m=65536,t=3,p=1$MDEyMzQ1Njc4OWFiY2RlZg$UK8wQh8PyocEgY7zRrNJQtvCpiKS/EbCJs3f3ZHk+Vg";
  private static final String PREVIOUS =
      "$argon2id$v=19$m=19456,t=2,p=1$MDEyMzQ1Njc4OWFiY2RlZg$NSs0yH3oMQld+x00Go1Bv5v8R/qdb5tQQ78tUAUHpyw";
  private final Argon2PasswordService adapter = new Argon2PasswordService();

  @Test
  void independentCurrentVectorMatchesWithoutUpgrade() {
    var result = adapter.verify(PASSWORD.toCharArray(), CURRENT);
    assertThat(result.matches()).isTrue();
    assertThat(result.upgradeRequired()).isFalse();
  }

  @Test
  void independentPreviousVectorSignalsUpgradeOnlyOnMatch() {
    assertThat(adapter.verify(PASSWORD.toCharArray(), PREVIOUS).upgradeRequired()).isTrue();
    var wrong = adapter.verify("wrong".toCharArray(), PREVIOUS);
    assertThat(wrong.matches()).isFalse();
    assertThat(wrong.upgradeRequired()).isFalse();
  }

  @ParameterizedTest
  @ValueSource(
      strings = {
        "wrong",
        "synthetic fixture é 👩‍💻",
        "synthetic fixture é 👩‍💻  ",
        "SYNTHETIC fixture é 👩‍💻  "
      })
  void noTrimmingNormalizationOrCaseFolding(String wrong) {
    assertThat(adapter.verify(wrong.toCharArray(), CURRENT).matches()).isFalse();
  }

  @Test
  void generatedHashesAreRandomCurrentProfileAndPreserveCallerArray() {
    char[] raw = "😀".repeat(128).toCharArray();
    char[] copy = raw.clone();
    String first = adapter.hash(raw);
    String second = adapter.hash(raw);
    assertThat(first).startsWith("$argon2id$v=19$m=65536,t=3,p=1$").isNotEqualTo(second);
    assertThat(adapter.verify(raw, first).matches()).isTrue();
    assertThat(raw).isEqualTo(copy);
    Arrays.fill(raw, '\0');
  }

  @Test
  void dummyNeverReturnsAuthenticationProofEvenWithTheFixturePassword() {
    adapter.consumeDummyCost(PASSWORD.toCharArray());
  }

  @Test
  void rejectsMalformedAndUnboundedPhcBeforeKdfWithFixedErrors() {
    for (String hash :
        new String[] {
          null,
          "",
          "x".repeat(10000),
          CURRENT + "=",
          CURRENT + "\n",
          CURRENT.replace("argon2id", "argon2i"),
          CURRENT.replace("v=19", "v=16"),
          CURRENT.replace("65536", "2147483647"),
          CURRENT.replace("t=3", "t=999999999"),
          CURRENT.replace("p=1", "p=256"),
          CURRENT.replace("65536", "065536"),
          CURRENT.replace("65536", "19456"),
          CURRENT.replace("65536", "16384"),
          CURRENT.replace("MDEy", "_DEy"),
          CURRENT.replace("Zg$", "Zh$"),
          CURRENT.substring(0, CURRENT.length() - 1) + "h",
          CURRENT.replace("Zg$", "Zg==$"),
          CURRENT.replace("m=65536,t=3,p=1", "t=3,m=65536,p=1"),
          CURRENT.replace("Zg$", "$"),
          CURRENT.replace("p=1$", "p=1,x=2$")
        }) {
      assertThatThrownBy(() -> adapter.verify("synthetic".toCharArray(), hash))
          .isInstanceOfSatisfying(
              CredentialDependencyException.class,
              ex -> {
                assertThat(ex.reason())
                    .isEqualTo(CredentialDependencyException.Reason.INVALID_STORED_HASH);
                assertThat(ex.getMessage()).isEqualTo("Credential dependency unavailable");
                assertThat(ex.getCause()).isNull();
              });
    }
  }

  @Test
  void invalidInputsDoNotEnterHashOrDummyWork() {
    for (char[] raw :
        new char[][] {
          null, new char[0], new char[257], new char[] {'\uD800'}, "a".repeat(129).toCharArray()
        }) {
      assertThatThrownBy(() -> adapter.hash(raw)).isInstanceOf(IllegalArgumentException.class);
      assertThatThrownBy(() -> adapter.verify(raw, CURRENT))
          .isInstanceOf(IllegalArgumentException.class);
      assertThatThrownBy(() -> adapter.consumeDummyCost(raw))
          .isInstanceOf(IllegalArgumentException.class);
    }
  }

  @Test
  void processBudgetIsSharedAcrossInstancesAndDoesNotQueue() throws Exception {
    CountDownLatch entered = new CountDownLatch(2);
    CountDownLatch release = new CountDownLatch(1);
    try (var pool = Executors.newFixedThreadPool(3)) {
      Callable<Boolean> hold =
          () ->
              KdfWorkBudget.run(
                  () -> {
                    entered.countDown();
                    try {
                      if (!release.await(5, TimeUnit.SECONDS))
                        throw new AssertionError("Test barrier timed out");
                    } catch (InterruptedException ex) {
                      Thread.currentThread().interrupt();
                      throw new AssertionError(ex);
                    }
                    return true;
                  });
      var one = pool.submit(hold);
      var two = pool.submit(hold);
      try {
        assertThat(entered.await(3, TimeUnit.SECONDS)).isTrue();
        pool.submit(
                () -> {
                  assertThatThrownBy(
                          () -> new Argon2PasswordService().verify(PASSWORD.toCharArray(), CURRENT))
                      .isInstanceOfSatisfying(
                          CredentialDependencyException.class,
                          ex ->
                              assertThat(ex.reason())
                                  .isEqualTo(
                                      CredentialDependencyException.Reason.CAPACITY_EXHAUSTED));
                  assertThatThrownBy(() -> adapter.hash(PASSWORD.toCharArray()))
                      .isInstanceOf(CredentialDependencyException.class);
                  assertThatThrownBy(() -> adapter.consumeDummyCost(PASSWORD.toCharArray()))
                      .isInstanceOf(CredentialDependencyException.class);
                  // Malformed hash validation must happen before attempting a budget slot.
                  assertThatThrownBy(() -> adapter.verify(PASSWORD.toCharArray(), "bad"))
                      .isInstanceOfSatisfying(
                          CredentialDependencyException.class,
                          ex ->
                              assertThat(ex.reason())
                                  .isEqualTo(
                                      CredentialDependencyException.Reason.INVALID_STORED_HASH));
                })
            .get(2, TimeUnit.SECONDS);
      } finally {
        release.countDown();
      }
      assertThat(one.get(2, TimeUnit.SECONDS)).isTrue();
      assertThat(two.get(2, TimeUnit.SECONDS)).isTrue();
    }
    assertThat(adapter.verify(PASSWORD.toCharArray(), CURRENT).matches()).isTrue();
  }

  @Test
  void budgetReturnsPermitAfterFailure() {
    for (int i = 0; i < 3; i++) {
      assertThatThrownBy(
              () ->
                  KdfWorkBudget.run(
                      () -> {
                        throw new IllegalStateException("synthetic");
                      }))
          .isInstanceOf(IllegalStateException.class);
    }
    assertThat(adapter.verify(PASSWORD.toCharArray(), CURRENT).matches()).isTrue();
  }
}
